def delete_subscription_filter(self, filter_name: str) -> None:
    # Find and remove the filter with the given name
    found = False
    updated_filters = []
    for filter in self.subscription_filters:
        if filter["filterName"] == filter_name:
            found = True
        else:
            updated_filters.append(filter)

    if not found:
        raise ResourceNotFoundException(
            "The specified subscription filter does not exist."
        )

    self.subscription_filters = updated_filters
